package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

type Node struct {
	Value int
	next *Node
	prev *Node
	root *Node
}

func (n *Node) Next() *Node {
	if n.next == n.root {
		return nil
	}
	return n.next
}

func (n *Node) Prev() *Node {
	if n.prev == n.root {
		return nil
	}
	return n.prev
}

type LList struct {
	root *Node
	size int
}

func NewLList() *LList {
	root := &Node{}
	root.next = root
	root.prev = root
	root.root = root
	return &LList{root: root, size: 0}
}

func (ll *LList) Size() int {
	return ll.size
}

func (ll * LList) Clear() {
	root := ll.root
	root.next = root
	root.prev = root
	ll.size = 0
}

func (ll *LList) PushFront(value int) {
	newNode:= &Node{Value: value, root: ll.root}
	root := ll.root
	first := root.next
	root.next = newNode
	newNode.prev = root
	newNode.next = first
	first.prev = newNode
	ll.size++
}

func (ll *LList) PushBack(value int) {
	newNode := &Node{Value: value, root: ll.root}
	root := ll.root
	last := root.prev
	last.next = newNode
	newNode.prev = last
	newNode.next = root
	root.prev = newNode
	ll.size++
}

func (ll *LList) PopFront() {
	if ll.size == 0 {
		return
	}
	root := ll.root
	first := root.next
	second := first.next
	root.next = second
	second.prev = root
	first.next = nil
	first.prev = nil
	first.root = nil
	ll.size--
}

func (ll *LList) PopBack() {
	if ll.size == 0 {
		return
	}
	root := ll.root
	last := root.prev
	prev := last.prev
	prev.next = root
	root.prev = prev
	last.next = nil
	last.prev = nil
	last.root = nil
	ll.size--
}

func (ll *LList) String() string {
	if ll.size == 0 {
		return "[]"
	}
	var sb strings.Builder
	sb.WriteString("[")

	node := ll.root.next
	for node != ll.root {
		if node != ll.root.next {
			sb.WriteString(", ")
		}
		sb.WriteString(strconv.Itoa(node.Value))
		node = node.next
	}
	sb.WriteString("]")
	return sb.String()
}

func (ll *LList) Front() *Node {
	if ll.size == 0 {
		return nil
	}
	return ll.root.next
}

func (ll *LList) Back() *Node {
	if ll.size == 0 {
		return nil
	}
	return ll.root.prev
}

func (ll *LList) Search(value int) *Node {
	node := ll.root.next
	for node != ll.root {
		if node.Value == value {
			return node
		}
		node = node.next
	}
	return nil
}

func (ll *LList) Insert(node *Node, value int) {
	if node == nil {
		return
	}
	newNode := &Node{Value: value, root: ll.root}
	prev := node.prev
	prev.next = newNode
	newNode.prev = prev
	newNode.next = node
	node.prev = newNode
	ll.size++
}

func (ll *LList) Remove(node *Node) *Node {
	if node == nil || node == ll.root {
		return nil
	}
	next := node.next
	prev := node.prev
	prev.next = next
	next.prev = prev
	node.next = nil
	node.prev = nil
	next.root = nil
	ll.size--
	if next == ll.root {
		return nil
	}
	return next
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	ll := NewLList()

	for {
		fmt.Print("$")
		if !scanner.Scan() {
			break
		}
		line := scanner.Text()
		fmt.Println(line)
		args := strings.Fields(line)

		if len(args) == 0 {
			continue
		}

		cmd := args[0]

		switch cmd {
		case "show":
			fmt.Println(ll.String())
		case "size":
			fmt.Println(ll.Size())
		case "push_back":
			for _, v := range args[1:] {
				num, _ := strconv.Atoi(v)
				ll.PushBack(num)
			}
		case "push_front":
			for _, v := range args[1:] {
				num, _ := strconv.Atoi(v)
				ll.PushFront(num)
			}
		case "pop_back":
			ll.PopBack()
		case "pop_front":
			ll.PopFront()
		case "clear":
			ll.Clear()
		case "walk":
			fmt.Print("[ ")
			for node := ll.Front(); node != nil; node = node.Next() {
				fmt.Printf("%v ", node.Value)
			}
			fmt.Print("]\n[ ")
			for node := ll.Back(); node != nil; node = node.Prev() {
				fmt.Printf("%v ", node.Value)
			}
			fmt.Println("]")
		case "replace":
			oldvalue, _ := strconv.Atoi(args[1])
			newvalue, _ := strconv.Atoi(args[2])
			node := ll.Search(oldvalue)
			if node != nil {
				node.Value = newvalue
			} else {
				fmt.Println("fail: not found")
			}
		case "insert":
			oldvalue, _ := strconv.Atoi(args[1])
			newvalue, _ := strconv.Atoi(args[2])
			node := ll.Search(oldvalue)
			if node != nil {
				ll.Insert(node, newvalue)
			} else {
				fmt.Println("fail: not found")
			}
		case "remove":
			oldvalue, _ := strconv.Atoi(args[1])
			node := ll.Search(oldvalue)
			if node != nil {
				ll.Remove(node)
			} else {
				fmt.Println("fail: not found")
			}
		case "end":
			return
		default:
			fmt.Println("fail: comando invalido")
		}
	}
}
